#version 330
in vec2 fragTexCoord; out vec4 finalColor;
uniform vec2 resolution; uniform float time; uniform float fade; uniform float fadeTarget;
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);} float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1)),f.x),f.y);} float fbm(vec2 p){float v=0.,a=.5;for(int i=0;i<5;i++){v+=a*noise(p);p=p*2.03+17.;a*=.5;}return v;} float box(vec2 p,vec2 b){vec2 d=abs(p)-b;return 1.-smoothstep(0.,.012,max(d.x,d.y));}
void main(){vec2 uv=gl_FragCoord.xy/resolution, p=(gl_FragCoord.xy-.5*resolution)/resolution.y;float t=time*.045,base=fbm(uv*4.+vec2(t*.18,-t*.05)),stains=fbm(uv*9.-vec2(t*.24,t*.11));vec3 col=vec3(.035,.032,.038)+base*vec3(.10,.065,.055)+stains*vec3(.07,.025,.045);float oil=fbm(uv*3.2+vec2(sin(t),cos(t*.7)));col+=smoothstep(.52,.78,oil)*vec3(.16,.018,.12)+smoothstep(.67,.82,fbm(uv*5.-t))*vec3(.02,.15,.07);for(int i=0;i<9;i++){float fi=float(i),x=-.95+fract(fi*.371)*1.9,w=.018+.04*fract(fi*.67),y=-.3+fract(fi*.193)*.95;col+=box(p-vec2(x,y),vec2(w,.5))*vec3(.12,.055,.025);col+=box(p-vec2(x+.015*sin(t+fi),y),vec2(.006,.5))*vec3(.2,.02,.12);}float cracks=abs(noise(uv*35.+t)-.5);col+=smoothstep(.46,.5,cracks)*vec3(.18,.06,.04);col+=sin((uv.y+t*.7)*resolution.y*.11)*.025;float tear=step(.985,fract(sin(floor(time*.18))*43758.))*step(.4,fract(uv.y*17.+time*.06));col+=tear*vec3(.12,.015,.08);float scratch=step(.965,hash(floor(uv*vec2(180.,100.))+floor(time*.08)));col+=scratch*vec3(.35,.18,.08)*(.3+.7*noise(uv*8.));float refl=exp(-abs(p.y-(.22+.08*sin(p.x*2.+t)))*45.)*smoothstep(.1,.8,fbm(uv*6.+t));col+=refl*vec3(.55,.20,.04)+exp(-abs(p.y+.18+.08*sin(p.x*3.-t))*65.)*vec3(.12,.01,.16);float vig=smoothstep(1.15,.28,length(p*vec2(.72,.95)));col*=.72+.28*vig;float f=clamp(fade,0.,1.);finalColor=vec4(mix(vec3(fadeTarget),clamp(col,0.,1.),f),1.);}
